CREATE FUNCTION public.reporting_claim_email(_invoice uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.reporting_invoices SET email_status='sending',updated_at=now() WHERE id=_invoice AND (email_status IN ('not_sent','failed') OR (email_status='sending' AND updated_at<now()-interval '15 minutes')); RETURN FOUND; END $$;
REVOKE ALL ON FUNCTION public.reporting_claim_email(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.reporting_claim_email(uuid) TO service_role;
CREATE FUNCTION public.reporting_claim_due(_account uuid,_due timestamptz) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.reporting_accounts SET last_attempt_at=now() WHERE id=_account AND enabled AND next_send_at=_due AND next_send_at<=now() AND (last_attempt_at IS NULL OR last_attempt_at<now()-interval '15 minutes'); RETURN FOUND; END $$;
REVOKE ALL ON FUNCTION public.reporting_claim_due(uuid,timestamptz) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.reporting_claim_due(uuid,timestamptz) TO service_role;